    matches = re.findall(pattern, s)

    for number, unit in matches:
        value = int(number)
        if unit == 's':
            total_seconds += value
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 'h':
            total_seconds += value * 3600

    # Handle bare numbers (no unit)
    if total_seconds == 0:
        # Check if there was a number without unit
        bare_match = re.search(r'\d+', s)
        if bare_match:
            total_seconds = int(bare_match.group())
    else:
        # Check if there's a bare number that wasn't captured
        bare_match = re.search(r'\d+(?![smh])', s)
        if bare_match:
            bare_value = int(bare_match.group())
            # Only add if it's not already part of the total
            if bare_value not in [int(n) for n, u in matches if u == '']:
                total_seconds += bare_value

    return total_seconds

