def clamp(x, lo, hi):
    # If lo is None, no lower bound
    if lo is None:
        if x > hi:
            return hi
        return x

    # If hi is None, no upper bound
    if hi is None:
        if x < lo:
            return lo
        return x

    # If lo > hi, swap them
    if lo > hi:
        lo, hi = hi, lo

    # Normal case
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x

