def word_count(s):
    if not s:
        return 0

    # Split by whitespace (handles multiple spaces as one separator)
    tokens = s.split()

    # Filter out tokens that are only punctuation
    words = []
    for token in tokens:
        # Check if token contains at least one alphanumeric character
        # This ensures tokens made only of punctuation are excluded
        if any(c.isalnum() for c in token):
            words.append(token)

    return len(words)

